ALTER TABLE public.projects ADD COLUMN IF NOT EXISTS start_date date, ADD COLUMN IF NOT EXISTS end_date date;
ALTER TABLE public.processes ADD COLUMN IF NOT EXISTS status text NOT NULL DEFAULT 'draft', ADD COLUMN IF NOT EXISTS entry_conditions text, ADD COLUMN IF NOT EXISTS completion_criteria text;
CREATE TABLE public.project_phases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.workspaces(id),project_id uuid NOT NULL REFERENCES public.projects(id),name text NOT NULL,position integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.project_phases TO authenticated; GRANT ALL ON public.project_phases TO service_role;
ALTER TABLE public.project_phases ENABLE ROW LEVEL SECURITY;
CREATE POLICY phases_read ON public.project_phases FOR SELECT TO authenticated USING(public.visible_record(workspace_id,'project',project_id));
CREATE TABLE public.project_participants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.workspaces(id),project_id uuid NOT NULL REFERENCES public.projects(id),user_id uuid NOT NULL,UNIQUE(project_id,user_id));
GRANT SELECT ON public.project_participants TO authenticated; GRANT ALL ON public.project_participants TO service_role;
ALTER TABLE public.project_participants ENABLE ROW LEVEL SECURITY;
CREATE POLICY participants_read ON public.project_participants FOR SELECT TO authenticated USING(public.visible_record(workspace_id,'project',project_id));
CREATE TABLE public.process_step_refs(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES public.workspaces(id),process_id uuid NOT NULL REFERENCES public.processes(id),UNIQUE(id,process_id,workspace_id));
GRANT SELECT ON public.process_step_refs TO authenticated; GRANT ALL ON public.process_step_refs TO service_role;
ALTER TABLE public.process_step_refs ENABLE ROW LEVEL SECURITY;
CREATE POLICY refs_read ON public.process_step_refs FOR SELECT TO authenticated USING(public.visible_record(workspace_id,'process',process_id));
INSERT INTO public.process_step_refs(id,workspace_id,process_id) SELECT (s->>'id')::uuid,p.workspace_id,p.id FROM public.processes p CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(p.steps)='array' THEN p.steps ELSE '[]'::jsonb END) s;
CREATE TABLE public.workflow_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.workspaces(id),project_id uuid NOT NULL REFERENCES public.projects(id),phase_id uuid REFERENCES public.project_phases(id),process_id uuid NOT NULL REFERENCES public.processes(id),name text NOT NULL,status text NOT NULL DEFAULT 'active',created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),version integer NOT NULL DEFAULT 1,notification_rules jsonb NOT NULL DEFAULT '{"assignment":true,"handoff":true,"approval":true,"reminder":true,"escalation":true,"escalation_hours":24}'::jsonb);
GRANT SELECT ON public.workflow_runs TO authenticated; GRANT ALL ON public.workflow_runs TO service_role;
ALTER TABLE public.workflow_runs ENABLE ROW LEVEL SECURITY;
CREATE POLICY runs_read ON public.workflow_runs FOR SELECT TO authenticated USING(public.visible_record(workspace_id,'project',project_id) AND public.visible_record(workspace_id,'process',process_id));
CREATE OR REPLACE FUNCTION public.workflow_can_read(_run uuid,_user uuid DEFAULT auth.uid()) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.workflow_runs r JOIN public.processes p ON p.id=r.process_id JOIN public.projects j ON j.id=r.project_id WHERE r.id=_run AND public.can_view_confidential(_user,r.workspace_id,p.created_by,coalesce(p.confidentiality,'internal')) AND public.can_view_confidential(_user,r.workspace_id,j.created_by,coalesce(j.confidentiality,'internal'))); $$;
REVOKE ALL ON FUNCTION public.workflow_can_read(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.workflow_can_read(uuid,uuid) TO authenticated,service_role;
CREATE TABLE public.workflow_steps(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.workspaces(id),run_id uuid NOT NULL REFERENCES public.workflow_runs(id),definition_id uuid NOT NULL REFERENCES public.process_step_refs(id),title text NOT NULL,position integer NOT NULL,owner_id uuid,department text NOT NULL DEFAULT '',assigned_users uuid[] NOT NULL DEFAULT '{}',due_date date,priority text NOT NULL DEFAULT 'medium',status text NOT NULL DEFAULT 'pending',completion_criteria text NOT NULL DEFAULT '',entry_conditions text NOT NULL DEFAULT '',entry_verified boolean NOT NULL DEFAULT false,criteria_verified boolean NOT NULL DEFAULT false,required_approvals integer NOT NULL DEFAULT 0,approver_ids uuid[] NOT NULL DEFAULT '{}',approval_requested boolean NOT NULL DEFAULT false,approval_expires_at timestamptz,version integer NOT NULL DEFAULT 1,quality_status text NOT NULL DEFAULT 'none',quality_owner_id uuid,corrective_title text NOT NULL DEFAULT 'Corrective action',quality_blocks boolean NOT NULL DEFAULT true,completed_at timestamptz,UNIQUE(run_id,definition_id),CONSTRAINT workflow_step_status CHECK(status IN('pending','in_progress','completed')),CONSTRAINT workflow_step_priority CHECK(priority IN('low','medium','high','critical')),CONSTRAINT workflow_step_approval_count CHECK(required_approvals BETWEEN 0 AND 10),CONSTRAINT workflow_step_quality CHECK(quality_status IN('none','failed','verified')));
GRANT SELECT ON public.workflow_steps TO authenticated; GRANT ALL ON public.workflow_steps TO service_role;
ALTER TABLE public.workflow_steps ENABLE ROW LEVEL SECURITY;
CREATE POLICY steps_read ON public.workflow_steps FOR SELECT TO authenticated USING(public.workflow_can_read(run_id));
CREATE TABLE public.workflow_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.workspaces(id),run_id uuid NOT NULL REFERENCES public.workflow_runs(id),step_id uuid NOT NULL REFERENCES public.workflow_steps(id),title text NOT NULL,assignee_id uuid NOT NULL,status text NOT NULL DEFAULT 'pending',due_date date,priority text NOT NULL DEFAULT 'medium',required boolean NOT NULL DEFAULT true,corrective boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT workflow_task_status CHECK(status IN('pending','in_progress','completed')),CONSTRAINT workflow_task_priority CHECK(priority IN('low','medium','high','critical')));
GRANT SELECT ON public.workflow_tasks TO authenticated; GRANT ALL ON public.workflow_tasks TO service_role;
ALTER TABLE public.workflow_tasks ENABLE ROW LEVEL SECURITY;
CREATE POLICY tasks_read ON public.workflow_tasks FOR SELECT TO authenticated USING(public.workflow_can_read(run_id));
CREATE UNIQUE INDEX one_active_correction ON public.workflow_tasks(step_id) WHERE corrective AND status<>'completed';
CREATE TABLE public.workflow_dependencies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.workspaces(id),run_id uuid NOT NULL REFERENCES public.workflow_runs(id),step_id uuid NOT NULL REFERENCES public.workflow_steps(id),prerequisite_id uuid NOT NULL REFERENCES public.workflow_steps(id),UNIQUE(step_id,prerequisite_id),CONSTRAINT no_self_dependency CHECK(step_id<>prerequisite_id));
GRANT SELECT ON public.workflow_dependencies TO authenticated; GRANT ALL ON public.workflow_dependencies TO service_role;
ALTER TABLE public.workflow_dependencies ENABLE ROW LEVEL SECURITY;
CREATE POLICY deps_read ON public.workflow_dependencies FOR SELECT TO authenticated USING(public.workflow_can_read(run_id));
CREATE TABLE public.workflow_approvals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.workspaces(id),run_id uuid NOT NULL REFERENCES public.workflow_runs(id),step_id uuid NOT NULL REFERENCES public.workflow_steps(id),step_version integer NOT NULL,approver_id uuid NOT NULL,vote text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(step_id,step_version,approver_id),CONSTRAINT workflow_vote CHECK(vote IN('approve','reject')));
GRANT SELECT ON public.workflow_approvals TO authenticated; GRANT ALL ON public.workflow_approvals TO service_role;
ALTER TABLE public.workflow_approvals ENABLE ROW LEVEL SECURITY;
CREATE POLICY votes_read ON public.workflow_approvals FOR SELECT TO authenticated USING(public.workflow_can_read(run_id));
CREATE TABLE public.workflow_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.workspaces(id),run_id uuid NOT NULL REFERENCES public.workflow_runs(id),step_id uuid REFERENCES public.workflow_steps(id),actor_id uuid,event_type text NOT NULL,request_id uuid NOT NULL UNIQUE,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.workflow_events TO authenticated; GRANT ALL ON public.workflow_events TO service_role;
ALTER TABLE public.workflow_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY events_read ON public.workflow_events FOR SELECT TO authenticated USING(public.workflow_can_read(run_id));
CREATE TRIGGER workflow_events_immutable BEFORE UPDATE OR DELETE ON public.workflow_events FOR EACH ROW EXECUTE FUNCTION public.audit_events_immutable();
CREATE TABLE public.workflow_deliveries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.workspaces(id),run_id uuid NOT NULL REFERENCES public.workflow_runs(id),event_key text NOT NULL,recipient_id uuid NOT NULL,notification_id uuid REFERENCES public.notifications(id),channel text NOT NULL DEFAULT 'in_app',status text NOT NULL DEFAULT 'persisted',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(event_key,recipient_id,channel));
GRANT SELECT ON public.workflow_deliveries TO authenticated; GRANT ALL ON public.workflow_deliveries TO service_role;
ALTER TABLE public.workflow_deliveries ENABLE ROW LEVEL SECURITY;
CREATE POLICY deliveries_read ON public.workflow_deliveries FOR SELECT TO authenticated USING(public.workflow_can_read(run_id) AND (recipient_id=auth.uid() OR public.is_workspace_admin(auth.uid(),workspace_id)));
CREATE OR REPLACE FUNCTION public.sync_process_step_refs() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s jsonb; BEGIN
 IF TG_OP='UPDATE' AND (NEW.workspace_id<>OLD.workspace_id OR NEW.created_by<>OLD.created_by) THEN RAISE EXCEPTION 'Process provenance is immutable'; END IF;
 IF jsonb_typeof(NEW.steps)='array' THEN
 IF (SELECT count(*) FROM jsonb_array_elements(NEW.steps))<>(SELECT count(DISTINCT (x->>'id')::uuid) FROM jsonb_array_elements(NEW.steps) x) THEN RAISE EXCEPTION 'Duplicate step identity'; END IF;
 FOR s IN SELECT value FROM jsonb_array_elements(NEW.steps) LOOP
 IF EXISTS(SELECT 1 FROM public.process_step_refs WHERE id=(s->>'id')::uuid AND process_id<>NEW.id) THEN RAISE EXCEPTION 'Step identity belongs to another process'; END IF;
 INSERT INTO public.process_step_refs(id,workspace_id,process_id) VALUES((s->>'id')::uuid,NEW.workspace_id,NEW.id) ON CONFLICT(id) DO NOTHING;
 END LOOP; END IF;
 IF EXISTS(SELECT 1 FROM public.process_step_refs ref WHERE ref.process_id=NEW.id AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(NEW.steps,'[]')) x WHERE (x->>'id')::uuid=ref.id)) THEN RAISE EXCEPTION 'Existing steps must be preserved; archive instead of removing'; END IF;
 RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.sync_process_step_refs() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER sync_step_registry AFTER INSERT OR UPDATE ON public.processes FOR EACH ROW EXECUTE FUNCTION public.sync_process_step_refs();
CREATE OR REPLACE FUNCTION public.workflow_assert_members(_workspace uuid,_ids uuid[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM unnest(_ids) u WHERE u IS NOT NULL AND NOT public.is_workspace_member(u,_workspace)) THEN RAISE EXCEPTION 'Assignees must belong to this workspace' USING ERRCODE='42501'; END IF; END; $$;
REVOKE ALL ON FUNCTION public.workflow_assert_members(uuid,uuid[]) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.workflow_notify(_run uuid,_recipient uuid,_key text,_kind text,_body text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d uuid; n uuid; ws uuid; BEGIN
 IF _recipient IS NULL OR NOT public.workflow_can_read(_run,_recipient) THEN RETURN; END IF;
 SELECT workspace_id INTO ws FROM public.workflow_runs WHERE id=_run;
 INSERT INTO public.workflow_deliveries(workspace_id,run_id,event_key,recipient_id) VALUES(ws,_run,_key,_recipient) ON CONFLICT DO NOTHING RETURNING id INTO d;
 IF d IS NULL THEN RETURN; END IF;
 INSERT INTO public.notifications(workspace_id,user_id,kind,title,body,link,severity,metadata) VALUES(ws,_recipient,_kind,_kind,_body,'/processes?run='||_run,'info',jsonb_build_object('run_id',_run,'event_key',_key)) RETURNING id INTO n;
 UPDATE public.workflow_deliveries SET notification_id=n WHERE id=d;
 END; $$;
REVOKE ALL ON FUNCTION public.workflow_notify(uuid,uuid,text,text,text) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.workflow_blockers(_step uuid,_completion boolean DEFAULT false) RETURNS text[] LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.workflow_steps%ROWTYPE; result text[]:='{}'; BEGIN
 SELECT * INTO s FROM public.workflow_steps WHERE id=_step;
 IF s.id IS NULL OR NOT public.workflow_can_read(s.run_id) THEN RAISE EXCEPTION 'Workflow access required' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM public.workflow_dependencies d JOIN public.workflow_steps p ON p.id=d.prerequisite_id WHERE d.step_id=s.id AND (p.status<>'completed' OR (p.quality_status='failed' AND p.quality_blocks))) THEN result:=array_append(result,'wf.block.dependencies'); END IF;
 IF s.entry_conditions<>'' AND NOT s.entry_verified THEN result:=array_append(result,'wf.block.entry'); END IF;
 IF s.quality_status='failed' AND s.quality_blocks THEN result:=array_append(result,'wf.block.quality'); END IF;
 IF _completion THEN
 IF EXISTS(SELECT 1 FROM public.workflow_tasks WHERE step_id=s.id AND required AND status<>'completed') THEN result:=array_append(result,'wf.block.tasks'); END IF;
 IF s.completion_criteria<>'' AND NOT s.criteria_verified THEN result:=array_append(result,'wf.block.criteria'); END IF;
 IF s.required_approvals>0 AND (NOT s.approval_requested OR (s.approval_expires_at IS NOT NULL AND s.approval_expires_at<=now()) OR EXISTS(SELECT 1 FROM public.workflow_approvals WHERE step_id=s.id AND step_version=s.version AND vote='reject') OR (SELECT count(*) FROM public.workflow_approvals a JOIN public.workspace_members m ON m.workspace_id=s.workspace_id AND m.user_id=a.approver_id AND m.role IN('admin','approver') WHERE a.step_id=s.id AND a.step_version=s.version AND a.vote='approve' AND (cardinality(s.approver_ids)=0 OR a.approver_id=ANY(s.approver_ids)))<s.required_approvals) THEN result:=array_append(result,'wf.block.approvals'); END IF;
 END IF; RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.workflow_blockers(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.workflow_blockers(uuid,boolean) TO authenticated,service_role;